'use client'
import { cn, focusElement, useSignal, useSignals } from '@cascivo/core'
import { useRef } from 'react'
import type { HTMLAttributes } from 'react'
import { t, builtin } from '@cascivo/i18n'
import styles from './tags-input.module.css'

export interface TagsInputProps extends Omit<HTMLAttributes<HTMLDivElement>, 'onChange'> {
  value: string[]
  onValueChange: (v: string[]) => void
  placeholder?: string
  validate?: (tag: string) => boolean
  max?: number
  /**
   * When true, disables the control and removes it from the tab order.
   *
   * @defaultValue `false`
   * @see the component manifest
   */
  disabled?: boolean
  /**
   * Id for the **inner text input** — the focusable control, so a `<label for>` names the
   * thing that actually takes focus. `Field` supplies this automatically.
   *
   * Naming is unaffected by this: the built-in name is dropped only when something actually
   * names the control (an `ariaLabel`/`label` prop, or the `aria-labelledby` a `Field`
   * supplies), so a standalone `<TagsInput id="x"/>` keeps its built-in name.
   */
  id?: string
  /**
   * Invisible accessible name for the tag entry field. Use when no visible label names it.
   *
   * Inside a `Field` you do not need this — the Field's label is wired through automatically.
   */
  ariaLabel?: string
  /**
   * Alias of `ariaLabel` — the same invisible accessible name under the other spelling. Not
   * rendered. `ariaLabel` is the catalog convention and stays preferred; `label` is the guess
   * an adopter makes when they have not read the convention, and an unaccepted guess costs a
   * compile cycle for nothing.
   */
  label?: string
}

export function TagsInput({
  value,
  onValueChange,
  placeholder,
  validate,
  max,
  disabled = false,
  className,
  id,
  ariaLabel,
  label,
  'aria-labelledby': ariaLabelledBy,
  'aria-describedby': ariaDescribedBy,
  'aria-invalid': ariaInvalid,
  ...props
}: TagsInputProps) {
  useSignals()
  const inputValue = useSignal('')
  const inputRef = useRef<HTMLInputElement>(null)

  /**
   * Accessible name for the inner input, most specific first.
   *
   * The built-in is LAST, not unconditional. It used to be hardcoded onto the input, and
   * because `aria-label` outranks a `<label for>` association it won even when a `Field`
   * wrapped the control — so `<Field label="Production domains">` produced a control named
   * "Tags", with the Field's hint unannounced. That is a WCAG 1.3.1/4.1.2 failure in the exact
   * composition the library prescribes (2026-08-22 report item 16).
   */
  const resolvedAriaLabel =
    ariaLabel ?? label ?? (ariaLabelledBy !== undefined ? undefined : t(builtin.tagsInput.label))

  function addTag(raw: string) {
    const tag = raw.trim()
    if (!tag) return
    if (max !== undefined && value.length >= max) return
    if (value.includes(tag)) return
    if (validate && !validate(tag)) return
    onValueChange([...value, tag])
    inputValue.value = ''
  }

  function removeTag(index: number) {
    onValueChange(value.filter((_, i) => i !== index))
  }

  const placeholderText = placeholder ?? t(builtin.tagsInput.placeholder)

  return (
    <div
      className={cn(styles['wrapper'], className)}
      data-disabled={disabled ? '' : undefined}
      onClick={() => focusElement(inputRef.current)}
      {...props}
    >
      {value.map((tag, i) => {
        const isInvalid = validate ? !validate(tag) : false
        return (
          <span key={i} className={styles['tag']} data-state={isInvalid ? 'invalid' : undefined}>
            {tag}
            <button
              type="button"
              className={styles['dismiss']}
              aria-label={t(builtin.tagsInput.remove, { tag })}
              disabled={disabled}
              onClick={(e) => {
                e.stopPropagation()
                removeTag(i)
              }}
            >
              <span aria-hidden="true">×</span>
            </button>
          </span>
        )
      })}
      <input
        ref={inputRef}
        className={styles['input']}
        value={inputValue.value}
        id={id}
        aria-labelledby={ariaLabelledBy}
        aria-describedby={ariaDescribedBy}
        aria-invalid={ariaInvalid}
        aria-label={resolvedAriaLabel}
        placeholder={value.length === 0 ? placeholderText : undefined}
        disabled={disabled}
        onChange={(e) => {
          inputValue.value = e.currentTarget.value
        }}
        onKeyDown={(e) => {
          if (e.key === 'Enter' || e.key === ',') {
            e.preventDefault()
            addTag(inputValue.value)
          } else if (e.key === 'Backspace' && !inputValue.value) {
            removeTag(value.length - 1)
          }
        }}
        onBlur={() => {
          if (inputValue.value) addTag(inputValue.value)
        }}
      />
    </div>
  )
}

@layer cascivo.component {
  .wrapper {
    /* A grid/flex item's default minimum is its content size, so a control with an
       intrinsic width (an <input> defaults to ~20ch) refuses to shrink and spills out of
       its track — reported as "Input overflows its grid cell" inside <Grid cols={{md:2}}>. */
    min-inline-size: 0;
    display: flex;
    flex-wrap: wrap;
    gap: var(--cascivo-space-1);
    min-height: 2.5rem;
    padding: var(--cascivo-space-2);
    background-color: var(--cascivo-color-surface);
    border: 1px solid var(--cascivo-color-border);
    border-radius: var(--cascivo-radius-field);
    cursor: text;
    transition:
      border-color var(--cascivo-duration-150) var(--cascivo-ease-out),
      box-shadow var(--cascivo-duration-150) var(--cascivo-ease-out);

    &:focus-within {
      border-color: var(--cascivo-color-accent);
      box-shadow: var(--cascivo-focus-ring);
    }

    /* Dim via muted colors, not opacity: a 0.5 wrapper opacity dropped the tag
       text below the WCAG contrast threshold. */
    &[data-disabled] {
      cursor: not-allowed;
      background-color: var(--cascivo-color-bg-subtle);
    }

    &[data-disabled] .tag {
      color: var(--cascivo-color-text-muted);
      border-color: var(--cascivo-color-border);
    }
  }

  .tag {
    display: inline-flex;
    align-items: center;
    gap: var(--cascivo-space-1);
    padding-block: var(--cascivo-space-1);
    padding-inline: var(--cascivo-space-2);
    font-family: var(--cascivo-font-sans);
    font-size: var(--cascivo-text-sm);
    color: var(--cascivo-color-text);
    background-color: var(--cascivo-color-bg-subtle);
    border: 1px solid var(--cascivo-color-border);
    border-radius: var(--cascivo-radius-full);
    line-height: 1.25;

    &[data-state='invalid'] {
      color: var(--cascivo-color-destructive);
      background-color: rgb(from var(--cascivo-color-destructive) r g b / 0.08);
      border-color: var(--cascivo-color-destructive);
    }
  }

  .dismiss {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1rem;
    height: 1rem;
    padding: 0;
    background: none;
    border: none;
    border-radius: var(--cascivo-radius-full);
    color: var(--cascivo-color-text-muted);
    cursor: pointer;
    font-size: var(--cascivo-text-sm);
    line-height: 1;

    &:hover {
      color: var(--cascivo-color-text);
      background-color: var(--cascivo-color-border);
    }

    &:focus-visible {
      outline: 2px solid var(--cascivo-color-accent);
      outline-offset: 1px;
    }

    &:disabled {
      cursor: not-allowed;
    }
  }

  .input {
    flex: 1;
    min-width: 4rem;
    background: none;
    border: none;
    outline: none;
    font-family: var(--cascivo-font-sans);
    font-size: var(--cascivo-text-sm);
    color: var(--cascivo-color-text);

    &::placeholder {
      color: var(--cascivo-color-text-muted);
    }

    &:disabled {
      cursor: not-allowed;
    }
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'TagsInput',
  description: 'Free-form multi-value chip input',
  category: 'inputs',
  // Adding and removing chips is the component; with JS off the value cannot change.
  clientJs: 'required',
  states: ['idle', 'focused', 'disabled'],
  variants: [],
  sizes: [],
  props: [
    { name: 'value', description: 'The controlled value.', type: 'string[]', required: true },
    {
      name: 'onValueChange',
      description: 'Called with the new value when it changes.',
      type: '(v: string[]) => void',
      required: true,
    },
    {
      name: 'placeholder',
      description: 'Placeholder text shown when the field is empty.',
      type: 'string',
      required: false,
    },
    {
      name: 'validate',
      description: 'Returns whether a candidate tag is allowed.',
      type: '(tag: string) => boolean',
      required: false,
    },
    { name: 'max', description: 'Maximum allowed value.', type: 'number', required: false },
    {
      name: 'disabled',
      description: 'When true, disables the control and removes it from the tab order.',
      type: 'boolean',
      required: false,
      default: 'false',
    },
    {
      name: 'id',
      description:
        'Id for the **inner text input** — the focusable control, so a `<label for>` names the thing that actually takes focus. `Field` supplies this automatically.',
      type: 'string',
      required: false,
    },
    {
      name: 'ariaLabel',
      description:
        'Invisible accessible name for the tag entry field. Use when no visible label names it; inside a `Field` it is not needed, as the Field label is wired through automatically.',
      type: 'string',
      required: false,
      nameVisibility: 'invisible',
    },
    {
      name: 'label',
      description:
        'Alias of `ariaLabel` — the same invisible accessible name under the other spelling. Not rendered.',
      type: 'string',
      required: false,
      nameVisibility: 'invisible',
    },
  ],
  tokens: [
    '--cascivo-color-surface',
    '--cascivo-color-border',
    '--cascivo-color-accent',
    '--cascivo-color-destructive',
    '--cascivo-color-bg-subtle',
    '--cascivo-radius-input',
    '--cascivo-radius-full',
    '--cascivo-focus-ring',
  ],
  accessibility: {
    role: 'textbox',
    wcag: '2.2-AA',
    keyboard: ['Enter', ',', 'Backspace'],
  },
  examples: [
    {
      title: 'Basic',
      code: `<TagsInput value={['react', 'vue']} onValueChange={() => {}} placeholder="Add tag…" />`,
    },
  ],
  dependencies: ['@cascivo/core', '@cascivo/i18n'],
  tags: ['form', 'tags', 'chips', 'multi', 'input'],
  intent: {
    whenToUse: [
      'Collecting an open-ended set of free-text values the user types themselves (keywords, emails, labels)',
      'Each entry should appear as a removable chip and there is no fixed list to pick from',
      'You need per-tag validation or a cap on how many entries are allowed',
    ],
    whenNotToUse: [
      'Values come from a fixed, known list — use MultiSelect',
      'Only a single line of free text is needed — use Input',
    ],
    antiPatterns: [
      {
        bad: '<TagsInput value={selectedRoles} ... /> // roles are a fixed enum',
        good: '<MultiSelect options={roleOptions} />',
        why: 'Free-text entry invites typos and inconsistent values when the set is actually constrained; pick from options instead',
      },
    ],
    related: [
      {
        name: 'MultiSelect',
        relationship: 'alternative',
        reason: 'Use when values come from a fixed list rather than free text',
      },
      {
        name: 'Input',
        relationship: 'alternative',
        reason: 'Use for a single free-text value with no chips',
      },
    ],
    a11yRationale:
      'The typing surface is a real <input> and each tag exposes a dedicated remove button with an aria-label naming the tag, so screen-reader users can both add (Enter/comma) and delete (Backspace or the button) without ambiguity.',
    content: {
      tone: 'Short, lowercase tag tokens; placeholder is an invite to add',
      notes: 'Placeholder defaults from the i18n catalog and only shows while empty',
    },
    flexibility: [
      {
        area: 'tag values',
        level: 'flexible',
        note: 'Free text, optionally constrained by the validate predicate and max count',
      },
      {
        area: 'commit keys',
        level: 'strict',
        note: 'Enter and comma commit a tag; Backspace on empty removes the last — fixed interaction contract',
      },
    ],
  },
}
